const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for Mesquite Flat and Panamint Mountains
  const mesquitFlat = ee.Geometry.Rectangle([-117.0, 36.3, -116.7, 36.5]);
  const panamintMountains = ee.Geometry.Rectangle([-117.2, 36.2, -116.85, 36.5]);

  // Filter Landsat 8 for June 30, 2013
  const startDate = '2013-06-30';
  const endDate = '2013-07-01';

  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(mesquitFlat.union(panamintMountains));

  const imgCount = collection.size().getInfo();
  console.log(`Images found for June 30, 2013: ${imgCount}`);

  if (imgCount === 0) {
    console.log('No Landsat 8 images found for this date.');
    console.log('C1');
    return;
  }

  // Get first image (should be only one for this date)
  const image = collection.first();

  // Apply QA pixel mask to remove clouds and bad pixels
  const qaPixel = image.select('QA_PIXEL');
  const cloudMask = qaPixel.bitwiseAnd(1 << 3).eq(0) // Cloud shadow
    .and(qaPixel.bitwiseAnd(1 << 4).eq(0)) // Cloud
    .and(qaPixel.bitwiseAnd(1 << 5).eq(0)); // Cloud confidence

  const maskedImage = image.select('ST_B10').updateMask(cloudMask);

  // Calculate LST stats for Mesquite Flat
  const mesquitStats = maskedImage.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: mesquitFlat,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const mesquitLST = mesquitStats.ST_B10_mean;
  const mesquitPixels = mesquitStats.ST_B10_count;

  console.log(`Mesquite Flat - LST: ${mesquitLST?.toFixed(2) || 'null'} K, Pixels: ${mesquitPixels || 0}`);

  // Calculate LST stats for Panamint Mountains
  const panamintStats = maskedImage.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: panamintMountains,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const panamintLST = panamintStats.ST_B10_mean;
  const panamintPixels = panamintStats.ST_B10_count;

  console.log(`Panamint Mountains - LST: ${panamintLST?.toFixed(2) || 'null'} K, Pixels: ${panamintPixels || 0}`);

  // Validate results
  if (mesquitPixels === 0 || panamintPixels === 0) {
    console.log('No valid pixels after masking.');
    console.log('C2');
    return;
  }

  if (mesquitLST === null || mesquitLST === undefined || panamintLST === null || panamintLST === undefined) {
    console.log('Invalid LST values.');
    console.log('C3');
    return;
  }

  if (mesquitLST > panamintLST) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
